/// <summary>
/// 触发本次回调的原生 DOM 事件。
/// </summary>
[ECMAScript]
[Union]
public readonly struct TListScrollEventOptionsE : IUnion
{
    // Native unions cannot retain an exact branch when one source type inherits another.
    // 保留显式 tag，避免派生 DOM 类型同时命中基类 AsX 投影。
    private readonly byte _kind;
    private readonly EventRef? _value1;
    private readonly WheelEvent? _value2;

    /// <summary>
    /// 使用 EventRef 值创建联合值，并保留当前分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    public TListScrollEventOptionsE(EventRef value)
    {
        _kind = 1;
        _value1 = value;
        _value2 = default;
    }

    /// <summary>
    /// 使用 WheelEvent 值创建联合值，并保留当前分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    public TListScrollEventOptionsE(WheelEvent value)
    {
        _kind = 2;
        _value1 = default;
        _value2 = value;
    }

    /// <summary>
    /// 读取 EventRef 分支；当前值属于其他分支时返回 null。
    /// </summary>
    public EventRef? AsEventRef => _kind == 1 ? _value1 : default;
    /// <summary>
    /// 读取 WheelEvent 分支；当前值属于其他分支时返回 null。
    /// </summary>
    public WheelEvent? AsWheelEvent => _kind == 2 ? _value2 : default;

    /// <summary>
    /// 读取当前分支的原始值；未初始化时返回 null。
    /// </summary>
    public object? Value => _kind switch
    {
        1 => AsEventRef,
        2 => AsWheelEvent,
        _ => default
    };

    /// <summary>
    /// 将 EventRef 值转换为对应的联合分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    /// <returns>保留当前分支的联合值。</returns>
    public static implicit operator TListScrollEventOptionsE(EventRef value)
        => new(value);

    /// <summary>
    /// 将 WheelEvent 值转换为对应的联合分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    /// <returns>保留当前分支的联合值。</returns>
    public static implicit operator TListScrollEventOptionsE(WheelEvent value)
        => new(value);

}

