    /// <summary>
    /// 列类名，值类型是 Function 使用返回值作为列类名；值类型不为 Function 时，值用于整列类名（含表头）。泛型 T 指表格数据类型
    /// </summary>
    [ECMAScriptName("className")]
    public TBaseTableColClassName<TTableRowData>? ClassName { get; init; }

    /// <summary>
    /// 渲染列所需字段，必须唯一。值为 `row-select` 表示当前列为行选中操作列。值为 `drag` 表示当前列为拖拽排序操作列。值为 `serial-number` 表示当前列为「序号」列
    /// 默认值：''
    /// </summary>
    [ECMAScriptName("colKey")]
    public string? ColKey { get; init; }

    /// <summary>
    /// 单行表头合并列。多行表头请参考「多级表头」文档示例
    /// </summary>
    [ECMAScriptName("colspan")]
    public Number? Colspan { get; init; }

    /// <summary>
    /// 单元格和表头内容超出时，是否显示省略号。如果仅希望单元格超出省略，可设置 `ellipsisTitle = false`。
    /// 值为 `true`，则超出省略浮层默认显示单元格内容；
    /// 值类型为 `Function` 则自定义超出省略浮中层显示的内容；
    /// 值类型为 `Object`，则自动透传属性到 Tooltip 组件，可用于调整浮层背景色和方向等特性。
    /// 同时透传 Tooltip 属性和自定义浮层内容，请使用 `{ props: { theme: 'light' }, content: () =&gt; 'something' }`。
    /// 请注意单元格超出省略的两个基本点：1. 内容元素是内联元素或样式（自定义单元格内容时需特别注意）；2. 内容超出父元素
    /// 默认值：false
    /// </summary>
    [ECMAScriptName("ellipsis")]
    public TBaseTableColEllipsis<TTableRowData>? Ellipsis { get; init; }

    /// <summary>
    /// 表头内容超出时，是否显示省略号。优先级高于 `ellipsis`。
    /// 值为 `true`，则超出省略的浮层默认显示表头全部内容；
    /// 值类型为 `Function` 用于自定义超出省略浮层显示的表头内容；
    /// 值类型为 `Object`，则自动透传属性到 Tooltip 组件，则自动透传属性到 Tooltip 组件，可用于调整浮层背景色和方向等特性。
    /// 同时透传 Tooltip 属性和自定义浮层内容，请使用 `{ props: { theme: 'light' }, content: () =&gt; 'something' }`
    /// </summary>
    [ECMAScriptName("ellipsisTitle")]
    public TBaseTableColEllipsisTitle<TTableRowData>? EllipsisTitle { get; init; }

    /// <summary>
    /// 固定列显示位置
    /// 默认值：left
    /// </summary>
    [ECMAScriptName("fixed")]
    public TBaseTableColFixed? Fixed { get; init; }

    /// <summary>
    /// 自定义表尾表尾。值类型为 Function 表示以函数形式渲染表尾内容。值类型为 string 表示使用插槽渲染，插槽名称为 `foot` 值
    /// </summary>
    [ECMAScriptName("foot")]
    public TBaseTableColFoot<TTableRowData>? Foot { get; init; }

    /// <summary>
    /// 透传 CSS 属性 `min-width` 到 `&lt;col&gt;` 元素。⚠️ 仅少部分浏览器支持，如：使用 [TablesNG](https://docs.google.com/document/d/16PFD1GtMI9Zgwu0jtPaKZJ75Q2wyZ9EZnVbBacOfiNA/preview) 渲染的 Chrome 浏览器支持 `minWidth`
    /// </summary>
    [ECMAScriptName("minWidth")]
    public TBaseTableColMinWidth<TTableRowData>? MinWidth { get; init; }

    /// <summary>
    /// 是否允许调整当前列列宽，一般用于设置为 `false` 禁止调整某一列列宽。如果是允许列宽调整，需要先设置 `BaseTable.resizable` 为 `true` 打开所有列宽调整
    /// 默认值：true
    /// </summary>
    [ECMAScriptName("resizable")]
    public bool? Resizable { get; init; }

    /// <summary>
    /// 限制拖拽调整的最小宽度和最大宽度。`resize.minWidth` 默认为 `80`，`resize.maxWidth` 默认为 `600`
    /// </summary>
    [ECMAScriptName("resize")]
    public TTableColumnResizeConfig? Resize { get; init; }

    /// <summary>
    /// 是否阻止当列单元格点击事件冒泡
    /// </summary>
    [ECMAScriptName("stopPropagation")]
    public bool? StopPropagation { get; init; }

    /// <summary>
    /// 列表头类名，值类型是函数时使用返回值作为列类名。泛型 T 指表格数据类型
    /// </summary>
    [ECMAScriptName("thClassName")]
    public TBaseTableColThClassName<TTableRowData>? ThClassName { get; init; }

    /// <summary>
    /// 列宽，可以作为最小宽度使用。当列宽总和小于 `table` 元素时，浏览器根据宽度设置情况自动分配宽度；当列宽总和大于 `table` 元素，表现为定宽。可以同时调整 `table` 元素的宽度来达到自己想要的效果
    /// </summary>
    [ECMAScriptName("width")]
    public TBaseTableColWidth<TTableRowData>? Width { get; init; }

    /// <summary>
