    /// </summary>
    [ECMAScriptName("cell")]
    public TPrimaryTableColCell<T>? Cell { get; init; }

    /// <summary>
    /// 透传参数，`colKey` 值为 `row-select` 时，配置有效。具体定义参考 Checkbox 组件 和 Radio 组件。泛型 T 指表格数据类型
    /// </summary>
    [ECMAScriptName("checkProps")]
    public TCheckProps<T>? CheckProps { get; init; }

    /// <summary>
    /// 用于多级表头，泛型 T 指表格数据类型
    /// </summary>
    [ECMAScriptName("children")]
    public TPrimaryTableCol<T>[]? Children { get; init; }

    /// <summary>
    /// 是否禁用行选中，`colKey` 值为 `row-select` 时，配置有效
    /// </summary>
    [ECMAScriptName("disabled")]
    public TPrimaryTableColDisabled<T>? Disabled { get; init; }

    /// <summary>
    /// 可编辑单元格配置项，具体属性参考文档 `TableEditableCellConfig` 描述
    /// </summary>
    [ECMAScriptName("edit")]
    public TTableEditableCellConfig<T>? Edit { get; init; }

    /// <summary>
    /// 过滤规则，支持多选(multiple)、单选(single)、输入框(input) 等三种形式。想要自定义过滤组件，可通过 `filter.component` 实现，自定义过滤组件需要包含参数 value 和事件 change。更多信息请查看当前页面中 `TableColumnFilter` 的详细文档
    /// </summary>
    [ECMAScriptName("filter")]
    public TTableColumnFilter? Filter { get; init; }

    /// <summary>
    /// 自定义表头或单元格，泛型 T 指表格数据类型
    /// </summary>
    [ECMAScriptName("render")]
    public RenderFragment<TPrimaryTableRenderParams<T>>? Render { get; init; }

    /// <summary>
    /// 当前列支持排序的方式，desc 表示当前列只能进行降序排列；asc 表示当前列只能进行升序排列；all 表示当前列既可升序排列，又可以降序排列
    /// 默认值：all
    /// </summary>
    [ECMAScriptName("sortType")]
    public TSortType? SortType { get; init; }

    /// <summary>
    /// 该列是否支持排序。值为 true 表示该列支持排序；值类型为函数，表示对本地数据 `data` 进行排序，返回值参考 [MDN Array.sort](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Array/sort)。泛型 T 指表格数据类型
    /// 默认值：false
    /// </summary>
    [ECMAScriptName("sorter")]
    public TPrimaryTableColSorter<T>? Sorter { get; init; }

    /// <summary>
    /// 自定义表头渲染。值类型为 Function 表示以函数形式渲染表头。值类型为 string 表示使用插槽渲染，插槽名称为 title 的值。优先级高于 render
    /// </summary>
    [ECMAScriptName("title")]
    public TPrimaryTableColTitle<T>? Title { get; init; }

    /// <summary>
    /// `colKey` 值为 `row-select` 时表示行选中列，有两种模式：单选和多选。 `type=single` 表示单选，`type=multiple` 表示多选
