/// <summary>
/// 触发本次回调的原生 DOM 事件。
/// </summary>
[ECMAScript]
[Union]
public readonly struct TTreeSelectChangeContextE<DataOption> : IUnion
{
    // Native unions cannot retain an exact branch when one source type inherits another.
    // 保留显式 tag，避免派生 DOM 类型同时命中基类 AsX 投影。
    private readonly byte _kind;
    private readonly MouseEvent? _value1;
    private readonly KeyboardEvent? _value2;
    private readonly EventRef? _value3;

    /// <summary>
    /// 使用 MouseEvent 值创建联合值，并保留当前分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    public TTreeSelectChangeContextE(MouseEvent value)
    {
        _kind = 1;
        _value1 = value;
        _value2 = default;
        _value3 = default;
    }

    /// <summary>
    /// 使用 KeyboardEvent 值创建联合值，并保留当前分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    public TTreeSelectChangeContextE(KeyboardEvent value)
    {
        _kind = 2;
        _value1 = default;
        _value2 = value;
        _value3 = default;
    }

    /// <summary>
    /// 使用 EventRef 值创建联合值，并保留当前分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    public TTreeSelectChangeContextE(EventRef value)
    {
        _kind = 3;
        _value1 = default;
        _value2 = default;
        _value3 = value;
    }

    /// <summary>
    /// 读取 MouseEvent 分支；当前值属于其他分支时返回 null。
    /// </summary>
    public MouseEvent? AsMouseEvent => _kind == 1 ? _value1 : default;
    /// <summary>
    /// 读取 KeyboardEvent 分支；当前值属于其他分支时返回 null。
    /// </summary>
    public KeyboardEvent? AsKeyboardEvent => _kind == 2 ? _value2 : default;
    /// <summary>
    /// 读取 EventRef 分支；当前值属于其他分支时返回 null。
    /// </summary>
    public EventRef? AsEventRef => _kind == 3 ? _value3 : default;

    /// <summary>
    /// 读取当前分支的原始值；未初始化时返回 null。
    /// </summary>
    public object? Value => _kind switch
    {
        1 => AsMouseEvent,
        2 => AsKeyboardEvent,
        3 => AsEventRef,
        _ => default
    };

    /// <summary>
    /// 将 MouseEvent 值转换为对应的联合分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    /// <returns>保留当前分支的联合值。</returns>
    public static implicit operator TTreeSelectChangeContextE<DataOption>(MouseEvent value)
        => new(value);

    /// <summary>
    /// 将 KeyboardEvent 值转换为对应的联合分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    /// <returns>保留当前分支的联合值。</returns>
    public static implicit operator TTreeSelectChangeContextE<DataOption>(KeyboardEvent value)
        => new(value);

    /// <summary>
    /// 将 EventRef 值转换为对应的联合分支。
    /// </summary>
    /// <param name="value">该分支的值。</param>
    /// <returns>保留当前分支的联合值。</returns>
    public static implicit operator TTreeSelectChangeContextE<DataOption>(EventRef value)
        => new(value);

}

