    public bool? Checkable { get; init; }

    /// <summary>
    /// 树数据，泛型 `T` 表示树节点 TS 类型
    /// 默认值：[]
    /// </summary>
    [ECMAScriptName("data")]
    public T[]? Data { get; init; }

    /// <summary>
