/// <summary>
/// EnhancedTable
///
/// 增强表格
/// </summary>
[ECMAScriptName("EnhancedTable")]
[ECMAScript("tdesign-vue-next/es/table/index.mjs")]
public class TEnhancedTable<T> : TContentComponentBase
{
    /// <summary>
    /// 树形结构中，拖拽排序前控制，返回值为 `true` 则继续排序；返回值为 `false` 则中止排序还原数据
