    /// <summary>
    /// 表单错误信息配置，示例：`{ idcard: '请输入正确的身份证号码', max: '字符长度不能超过 ${max}' }`
    /// </summary>
    [Parameter]
    [ECMAScriptName("errorMessage")]
    public TFormErrorMessage? ErrorMessage { get; set; }

