    /// 示例一：{ draggable: true }，
    /// 示例二：[{ draggable: true }, { title: '超出省略显示' }]。
    /// 示例三：() =&gt; [{ draggable: true }]
    /// </summary>
    [Parameter]
    [ECMAScriptName("rowAttributes")]
