/// <summary>
/// Tooltip
///
/// 文字提示
/// </summary>
[ECMAScriptName("Tooltip")]
[ECMAScript("tdesign-vue-next/es/tooltip/index.mjs")]
public sealed class TTooltip : TContentComponentBase
{
    /// <summary>
    /// 指定挂载节点。数据类型为 String 时，会被当作选择器处理，进行节点查询。示例：'body' 或 () =&gt; document.body
    /// 默认值：'body'
